all-trust-checks-pass:agent_surface:
package surface.policy

default allow := false

allow if {
  count(input.trust_check_results.target) > 0
  every r in input.trust_check_results.target { r.ok }
}

allow-by-jwt-claim:agent_surface:
package surface.policy

default allow := false

jwt_claim_values(v) := [v] if is_string(v)

jwt_claim_values(v) := v if is_array(v)

allow if {
  input.source_auth.method == "jwt_bearer"
  some v in jwt_claim_values(input.source_auth.claims["role"])
  v in {"admin"}
}

allow-by-jwt-issuer-audience:agent_surfa:
package surface.policy

default allow := false

jwt_audiences contains a if {
  a := input.source_auth.claims.aud
  is_string(a)
}

jwt_audiences contains a if {
  is_array(input.source_auth.claims.aud)
  some a in input.source_auth.claims.aud
}

allow if {
  input.source_auth.method == "jwt_bearer"
  input.source_auth.claims.iss in {"https://login.example.com"}
  some a in jwt_audiences
  a in {"https://gateway.example.com"}
}

