allow-path-prefixes:agent_surface:
package surface.policy

default allow := false

allow if {
  some prefix in {"/public/"}
  startswith(input.http.path, prefix)
  not contains(input.http.path, "..")
  not contains(lower(input.http.path), "%2e")
  not contains(input.http.path, "\\")
  not contains(lower(input.http.path), "%5c")
}

