business-hours-access-window:agent_surfa:
package surface.policy

default allow := false

allow if in_access_window

in_access_window if {
  access_day
  access_minute >= 540
  access_minute < 1020
}

in_access_window if {
  540 > 1020
  access_day
  access_minute >= 540
}

in_access_window if {
  540 > 1020
  access_day
  access_minute < 1020
}

access_minute := (hour * 60) + minute if {
  [hour, minute, _] := time.clock([time.now_ns(), "UTC"])
}

access_day if count({"Monday", "Tuesday", "Wednesday", "Thursday", "Friday"}) == 0

access_day if time.weekday([time.now_ns(), "UTC"]) in {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday"}

