  input.agent.did
  input.agent.trust_verification == true
}

require-verified-credential-subject:agen:
package surface.policy

default allow := false

allow if {
  input.extension_identity.verified == true
  input.extension_identity.did in {"did:web:agent.example.com"}
}

restrict-mcp-tools-by-role:agent_surface:
package surface.policy

default allow := false

allow if {
  input.source_auth.claims.role in {"admin"}
  input.mcp.method == "tools/call"
}

allow if {
  input.source_auth.subject
  input.mcp.method == "tools/call"
  input.mcp.tool_name in {"search", "summarise", "translate"}
}

allow if {
  input.source_auth.subject
  input.mcp.method != "tools/call"
}

